# Golden values for phn-epi spc.rs control-chart centers and limits (qcc 2.7).
# Run: Rscript spc.R > ../spc.json
suppressPackageStartupMessages({library(qcc); library(jsonlite)})
x <- c(32, 28, 35, 30, 41, 29, 33, 36, 27, 31, 34, 38, 30, 29, 33, 52, 31, 30, 28, 35)
num <- c(12, 9, 15, 11, 8, 14, 10, 13, 9, 16, 11, 12, 30, 10, 12)
den <- c(150, 120, 180, 160, 110, 170, 140, 150, 130, 190, 150, 160, 155, 140, 150)
cnt <- c(4, 6, 3, 5, 7, 2, 4, 5, 9, 3, 6, 4, 5, 16, 4, 5)
expo <- c(1200, 1350, 1100, 1250, 1400, 1150, 1300, 1280, 1500, 1180, 1320, 1260, 1290, 1310, 1240, 1270)
lim <- function(q) list(center = unname(q$center), lcl = unname(q$limits[, 1]), ucl = unname(q$limits[, 2]),
                         beyond = unname(q$violations$beyond.limits))
i <- qcc(x, type = "xbar.one", plot = FALSE)
p <- qcc(num, sizes = den, type = "p", plot = FALSE)
u <- qcc(cnt, sizes = expo, type = "u", plot = FALSE)
cc <- qcc(cnt, type = "c", plot = FALSE)
ib <- qcc(x[1:12], newdata = x[13:20], type = "xbar.one", plot = FALSE)
cat(toJSON(list(note = "Generated by tests/fixtures/generators/spc.R (qcc: xbar.one with MR/d2 sigma, p, u, c; 1-based beyond-limit indices).",
                r_version = R.version.string, qcc_version = as.character(packageVersion("qcc")),
                x = x, num = num, den = den, cnt = cnt, expo = expo,
                xmr = lim(i), p = lim(p), u = lim(u), c = lim(cc),
                xmr_baseline12 = list(center = unname(ib$center), lcl = unname(ib$limits[1, 1]), ucl = unname(ib$limits[1, 2]))),
           auto_unbox = TRUE, digits = NA, pretty = TRUE))
